USE fcsa

IF OBJECT_ID('hulme.character_set') IS NOT NULL DROP TABLE hulme.character_set

CREATE TABLE hulme.character_set
(
    [dec000] [tinyint] NOT NULL,
	[hex000] [char](2) NOT NULL, 
    [chr000] [char](1) NOT NULL, 
    [dec032] [tinyint] NOT NULL,
	[hex032] [char](2) NOT NULL, 
    [chr032] [char](1) NOT NULL, 
    [dec064] [tinyint] NOT NULL,
	[hex064] [char](2) NOT NULL, 
    [chr064] [char](1) NOT NULL, 
    [dec096] [tinyint] NOT NULL,
	[hex096] [char](2) NOT NULL, 
    [chr096] [char](1) NOT NULL, 
    [dec128] [tinyint] NOT NULL,
	[hex128] [char](2) NOT NULL, 
    [chr128] [char](1) NOT NULL,
    [dec160] [tinyint] NOT NULL,
	[hex160] [char](2) NOT NULL, 
    [chr160] [char](5) NOT NULL, 
    [dec192] [tinyint] NOT NULL,
	[hex192] [char](6) NOT NULL, 
    [chr192] [char](1) NOT NULL,
    [dec224] [tinyint] NOT NULL,
	[hex224] [char](2) NOT NULL, 
    [chr224] [char](1) NOT NULL, 
 CONSTRAINT [PK_character_set] PRIMARY KEY CLUSTERED  
( 
    [dec000] ASC 
)WITH (PAD_INDEX = OFF, STATISTICS_NORECOMPUTE = ON, IGNORE_DUP_KEY = OFF, ALLOW_ROW_LOCKS = ON, ALLOW_PAGE_LOCKS = ON, FILLFACTOR = 80) ON [PRIMARY] 
) ON [PRIMARY];

